from copy import deepcopy
from solution import schedule

jobs = {
    \"z\": [\"b\", \"a\", \"b\"], \"a\": [], \"b\": [], \"c\": [\"a\"], \"d\": [\"z\", \"c\"],
    \"loop\": [\"loop\"], \"left\": [\"right\"], \"right\": [\"left\"], \"child\": [\"left\"],
    \"grandchild\": [\"child\"],
}
original = deepcopy(jobs)
assert schedule(jobs) == {
    \"waves\": [[\"a\", \"b\"], [\"c\", \"z\"], [\"d\"]],
    \"blocked\": [\"child\", \"grandchild\", \"left\", \"loop\", \"right\"],
}
assert jobs == original
assert schedule({\"x\": [\"x\", \"z\", \"z\"], \"y\": [\"a\"]}) == {\"missing\": [\"a\", \"z\"]}
